def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append((oid, opp))

    if not alive_opps:
        return float(min(budget, 20.0 if hp > 3 else 45.0))

    prev_bids = []
    cindy_prev = None
    dangerous_prev = 0.0
    rich_alive = 0
    urgent_opp_count = 0

    for oid, opp in alive_opps:
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_alive += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            b = float(bid)
            prev_bids.append(b)
            if b > dangerous_prev:
                dangerous_prev = b
            if oid == 'Cindy':
                cindy_prev = b

    slots = max(1.0, supply / float(WATER_REQ))
    scarce = supply <= 16.5
    ample = supply >= 23.0

    if cindy_prev is None:
        cindy_prev = 69.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(88.0, cindy_prev + 4.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(72.0, cindy_prev + 2.0 if scarce else cindy_prev - 4.0)
    else:
        if ample and urgent_opp_count == 0:
            bid = 26.0
        elif ample:
            bid = 34.0
        elif scarce:
            bid = max(58.0, cindy_prev - 6.0)
        else:
            bid = max(44.0, min(66.0, cindy_prev - 10.0))

    if rich_alive >= 2:
        bid += 6.0
    elif rich_alive == 0 and hp > 4 and no_water_days == 0:
        bid -= 4.0

    if dangerous_prev >= 100.0 and hp > 4 and no_water_days == 0:
        bid = min(bid, 38.0)

    if day >= 8:
        bid += 8.0
    if day >= 9 and hp <= 4:
        bid += 10.0

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if hp > 4 and no_water_days == 0 and days_left >= 2:
        reserve_floor = DAILY_SALARY * 1.2
    max_spend = max(0.0, budget - reserve_floor)
    if hp <= 3 or no_water_days >= 1:
        max_spend = budget

    bid = min(bid, max_spend if max_spend > 0 else budget)
    bid = max(0.0, min(bid, budget))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 5.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if my_status['hp'] <= 3:
            return min(my_status['budget'], max_prev + 5.0)
        return min(my_status['budget'], max(DAILY_SALARY * 0.4, max_prev * 0.8))

    return min(my_status['budget'], DAILY_SALARY * 0.5)
